var policyNo = bh.input.params.policyNo;

console.log("policyNo:", policyNo);

bh.local.GetQuery =
    "SELECT * FROM policies WHERE policy_no = '" + policyNo + "'";

var notexists = bh.local.GetResult.length == 0;

if (notexists) {

    bh.local.statusCode = 404;

    let msg = "Policy Not Found";

    bh.local.responseBody = {
        error: msg
    };

    throw new Error(msg);
}


// Policy exists
var policy = bh.local.GetResult[0];


// Check policy status
if (String(policy.status).toUpperCase() !== "ACTIVE") {

    bh.local.statusCode = 404;

    let msg = "Policy is not ACTIVE";

    bh.local.responseBody = {
        error: msg
    };

    throw new Error(msg);
}


// Policy found and ACTIVE
bh.local.statusCode = 200;

bh.local.responseBody = policy;

const BASE_URL =
    bh.system.environment.REELS_BASE_URL;

const TOKEN =
    bh.system.environment.REELS_TOKEN;

const PART_GROUP_DATASET_ID =
    "72b58c39-817f-4204-95dc-4f5eec8fd929";

const PART_GROUP_MDM_ID =
    "284f6b9e-8f83-4359-af14-3a3d51e9755e";

const PART_GROUP_ENTITY_ID =
    "5e37b7ae-e8d3-4e16-a404-ed577e40161a";

const LOSS_TYPE_DATASET_ID =
    "72b58c39-817f-4204-95dc-4f5eec8fd929";

const LOSS_TYPE_MDM_ID =
    "5caf278d-1c55-492e-a1c3-c7686fe07a99";

const LOSS_TYPE_ENTITY_ID =
    "97128efa-bdfe-4b79-941c-c8a980b381c4";


const buildUrl = (datasetId, mdmId, entityId) =>
    `${BASE_URL}/integration/api/records/filter/${datasetId}/${mdmId}/${entityId}`;


bh.local.headers = {
    token: TOKEN,
    "Content-Type": "application/json"
};


bh.local.requestBody = {
    pageNumber: 0,
    pageSize: 100,
    filter: {},
    multiplicity: "multiple",
    totalCount: true
};


bh.local.partGroupUrl =
    buildUrl(
        PART_GROUP_DATASET_ID,
        PART_GROUP_MDM_ID,
        PART_GROUP_ENTITY_ID
    );


bh.local.lossTypeUrl =
    buildUrl(
        LOSS_TYPE_DATASET_ID,
        LOSS_TYPE_MDM_ID,
        LOSS_TYPE_ENTITY_ID
    );


console.log("Motor OD master-data URLs prepared");

console.log(
    "partGroup:",
    bh.local.partGroupUrl
);

console.log(
    "lossType:",
    bh.local.lossTypeUrl
);

const getRecords = (response) =>
    response?.payload?.records ||
    response?.records ||
    [];

bh.local.masterDataResponse = {

    partGroups:
        getRecords(bh.local.partGroupResponse),

    lossTypes:
        getRecords(bh.local.lossTypeResponse)

};

console.log(
    "Motor OD Master Data Response:",
    JSON.stringify(
        bh.local.masterDataResponse,
        null,
        2
    )
);

bh.input.masterDataResponse =
    bh.local.masterDataResponse;

const body = bh.input.body || {};
bh.local.policyNo=body.policyNo;
bh.local.lossDate=body.lossDate;

bh.local.GetQuery =
    "SELECT * FROM policies " +
    "WHERE policy_no = '" +
    bh.local.policyNo +
    "' " +
    "AND status = 'ACTIVE'";

console.log("bh.local.GetQuery",bh.local.GetQuery)
const SETTLEMENT_DATASET_ID =
    "72b58c39-817f-4204-95dc-4f5eec8fd929";

const SETTLEMENT_MDM_ID =
    "96418f46-a2f2-46a8-85fa-a579796fc703";

const SETTLEMENT_ENTITY_ID =
    "7da6f6a6-00db-456e-966d-a3a96adb8eca";


const BASE_URL =
    bh.system.environment.REELS_BASE_URL;

const TOKEN =
    bh.system.environment.REELS_TOKEN;

    const buildUrl = (datasetId, mdmId, entityId) =>
    `${BASE_URL}/integration/api/records/filter/${datasetId}/${mdmId}/${entityId}`;


bh.local.headers = {
    token: TOKEN,
    "Content-Type": "application/json"
};


bh.local.requestBody = {
    pageNumber: 0,
    pageSize: 100,
    filter: {},
    multiplicity: "multiple",
    totalCount: true
};


bh.local.settlementUrl =
    buildUrl(
        SETTLEMENT_DATASET_ID,
        SETTLEMENT_MDM_ID,
        SETTLEMENT_ENTITY_ID
    );
console.log("bh.local.settlementUrl",bh.local.settlementUrl)

console.log("========================================");
console.log("START POLICY & COVER VALIDATION");
console.log("========================================");


// ============================================================
// 1. INITIALIZE DEFAULT RESPONSE
// ============================================================

bh.local.isValid = true;

bh.local.statusCode = 200;

bh.local.responseBody = {
    isValid: true
};


// ============================================================
// 2. GET INTIMATION WINDOW FROM SETTLEMENT PARAMETERS REEL
// ============================================================

console.log(
    "bh.local.settlementResponse",
    bh.local.settlementResponse
);

var records =
    bh.local.settlementResponse?.payload?.records ||
    bh.local.settlementResponse?.records ||
    [];

var intimationWindowDays = null;

for (var i = 0; i < records.length; i++) {

    var parameterKey =
        records[i]["Key"];

    var parameterValue =
        records[i]["Value"];

    if (
        String(parameterKey).trim() ===
        "INTIMATION_WINDOW_DAYS"
    ) {

        intimationWindowDays =
            Number(parameterValue);

        break;
    }
}

bh.local.intimationWindowDays =
    intimationWindowDays;

console.log(
    "INTIMATION_WINDOW_DAYS:",
    bh.local.intimationWindowDays
);


// ============================================================
// 3. VALIDATE INTIMATION WINDOW PARAMETER
// ============================================================

if (
    bh.local.intimationWindowDays === null ||
    isNaN(bh.local.intimationWindowDays)
) {

    console.log(
        "INTIMATION_WINDOW_DAYS parameter not found"
    );

    bh.local.isValid = false;
}


// ============================================================
// 4. CHECK POLICY RESULT
// ============================================================

console.log(
    "bh.local.GetResult",
    bh.local.GetResult
);

if (
    bh.local.isValid &&
    (
        !bh.local.GetResult ||
        bh.local.GetResult.length === 0
    )
) {

    console.log(
        "Policy Not Found"
    );

    bh.local.isValid = false;
}


// ============================================================
// 5. GET POLICY
// ============================================================

var policy = null;

if (
    bh.local.isValid
) {

    policy =
        bh.local.GetResult[0];

    console.log(
        "policy",
        policy
    );
}


// ============================================================
// 6. CHECK POLICY STATUS
// ============================================================

if (
    bh.local.isValid &&
    policy
) {

    if (
        String(policy.status).toUpperCase() !==
        "ACTIVE"
    ) {

        console.log(
            "Policy is not ACTIVE"
        );

        bh.local.isValid = false;
    }
}


// ============================================================
// 7. READ LOSS DATE
// ============================================================

var lossDate = null;

if (
    bh.local.isValid
) {

    lossDate =
        new Date(bh.local.lossDate);

    if (
        isNaN(lossDate.getTime())
    ) {

        console.log(
            "Invalid Date of Loss"
        );

        bh.local.isValid = false;
    }
}


// ============================================================
// 8. CREATE TODAY DATE
// ============================================================

var today =
    new Date();

today.setHours(
    0,
    0,
    0,
    0
);

if (
    lossDate
) {

    lossDate.setHours(
        0,
        0,
        0,
        0
    );
}


// ============================================================
// 9. LOG DATES
// ============================================================

if (
    lossDate
) {

    console.log(
        "Today:",
        today.toISOString().split("T")[0]
    );

    console.log(
        "Loss Date:",
        lossDate.toISOString().split("T")[0]
    );
}


// ============================================================
// 10. FUTURE DATE VALIDATION
// ============================================================

if (
    bh.local.isValid &&
    lossDate
) {

    if (
        lossDate > today
    ) {

        console.log(
            "Date of Loss is in the future"
        );

        bh.local.isValid = false;
    }
}


// ============================================================
// 11. POLICY PERIOD VALIDATION
// ============================================================

var policyStart = null;
var policyEnd = null;

if (
    bh.local.isValid &&
    policy &&
    lossDate
) {

    policyStart =
        new Date(
            policy.policy_start_date
        );

    policyEnd =
        new Date(
            policy.policy_end_date
        );

    policyStart.setHours(
        0,
        0,
        0,
        0
    );

    policyEnd.setHours(
        0,
        0,
        0,
        0
    );

    console.log(
        "Policy Start:",
        policyStart.toISOString().split("T")[0]
    );

    console.log(
        "Policy End:",
        policyEnd.toISOString().split("T")[0]
    );


    if (
        lossDate < policyStart ||
        lossDate > policyEnd
    ) {

        console.log(
            "Date of Loss is outside policy period"
        );

        bh.local.isValid = false;
    }
}


// ============================================================
// 12. INTIMATION WINDOW VALIDATION
// ============================================================

var differenceDays = null;

if (
    bh.local.isValid &&
    lossDate
) {

    var differenceMs =
        today.getTime() -
        lossDate.getTime();

    differenceDays =
        Math.floor(
            differenceMs /
            (1000 * 60 * 60 * 24)
        );

    console.log(
        "Days since loss:",
        differenceDays
    );

    console.log(
        "Maximum allowed days:",
        bh.local.intimationWindowDays
    );


    if (
        differenceDays >
        Number(
            bh.local.intimationWindowDays
        )
    ) {

        console.log(
            "Intimation window exceeded"
        );

        bh.local.isValid = false;
    }
}


// ============================================================
// 13. FINAL RESPONSE
// ============================================================

bh.local.statusCode = 200;

bh.local.responseBody = {
    isValid: bh.local.isValid
};


console.log(
    "========================================"
);

console.log(
    "FINAL VALIDATION RESULT:",
    bh.local.isValid
);

console.log(
    "FINAL RESPONSE BODY:",
    bh.local.responseBody
);

console.log(
    "FINAL STATUS CODE:",
    bh.local.statusCode
);

console.log(
    "========================================"
);

const CLIENT_ID =
    bh.system.environment.CASE_SERVICE_CLIENT_ID;

const CLIENT_SECRET =
    bh.system.environment.CASE_SERVICE_CLIENT_SECRET;

console.log("========== FINAL RESPONSE ==========");

const result =
    bh.local.GetResult &&
    bh.local.GetResult.length > 0
        ? bh.local.GetResult[0]
        : null;

console.log(
    "SQL Result:",
    JSON.stringify(result, null, 2)
);

if (!result) {

    bh.local.responseStatus = 500;

    bh.local.response = {
        success: false,
        message: "Claim creation failed"
    };

} else {

    bh.local.claimId =
        result.claim_id;

    bh.local.claimStatus =
        result.status;

    bh.local.responseStatus = 201;

    bh.local.response = {
        success: true,
        claimId: result.claim_id,
        status: result.status
    };
}

console.log(
    "Response Status:",
    bh.local.responseStatus
);

console.log(
    "Response Body:",
    JSON.stringify(
        bh.local.response,
        null,
        2
    )
);
// =====================================================
// TOKEN REQUEST
// =====================================================

bh.local.caseTokenUrl =
    "https://ids-ctr-pt.neutrinos-apps.com/token";

bh.local.caseTokenBody =
    "grant_type=client_credentials" +
    "&client_id=" +
    encodeURIComponent(CLIENT_ID) +
    "&client_secret=" +
    encodeURIComponent(CLIENT_SECRET);

bh.local.caseTokenHeaders = {
    "Content-Type":
        "application/x-www-form-urlencoded",
    "Accept":
        "application/json"
};

console.log(
    "TOKEN URL:",
    bh.local.caseTokenUrl
);

const rawTokenResponse =
    bh.local.caseTokenResponse || {};

const tokenResponse =
    rawTokenResponse &&
    rawTokenResponse.payload &&
    typeof rawTokenResponse.payload === "object"
        ? rawTokenResponse.payload
        : rawTokenResponse;


console.log(
    "========== CASE TOKEN RESPONSE =========="
);

console.log(
    JSON.stringify(
        tokenResponse,
        null,
        2
    )
);


// =====================================================
// EXTRACT TOKEN
// =====================================================

if (
    !tokenResponse.access_token ||
    typeof tokenResponse.access_token !== "string" ||
    !tokenResponse.access_token.trim()
) {

    bh.local.caseTokenSuccess = false;

    bh.local.caseAccessToken = "";

    throw new Error(
        "Case Service authentication failed: access token missing."
    );
}


bh.local.caseTokenSuccess = true;

bh.local.caseAccessToken =
    tokenResponse.access_token.trim();


console.log(
    "Case Service authentication successful."
);


// =====================================================
// CASE CREATE URL
// =====================================================

bh.local.caseCreationUrl =
    "https://alpha-pt.neutrinos-apps.com" +
    "/caseservice/case/instance/create?branch=main";


// =====================================================
// CASE CREATE HEADERS
// =====================================================

bh.local.caseCreationHeaders = {

    "Authorization":
        "Bearer " +
        bh.local.caseAccessToken,

    "Content-Type":
        "application/json",

    "Accept":
        "application/json"
};


console.log(
    "========== CASE CREATION REQUEST =========="
);

console.log(
    "URL:",
    bh.local.caseCreationUrl
);

console.log(
    "Token available:",
    !!bh.local.caseAccessToken
);

console.log(
    "============================================"
);
const body =
    bh.local.claimInput ||
    bh.input.body ||
    {};


// =====================================================
// CASE REQUEST
// =====================================================

bh.local.caseCreationRequest = {

    caseType: "motor_ragu",

    caseData: {

        claimId:
            bh.local.claimId,

        policyNumber:
            String(body.policyNo || ""),

        customerName:
            String(body.customerName || ""),

        vehicleRegistration:
            String(body.vehicleRegistration || ""),

        vehicleType:
            String(body.vehicleType || ""),

        yearOfManufacture:
            String(body.yearOfManufacture || ""),

        idv:
            String(body.idv || ""),

        policyStartDate:
            String(body.policyStartDate || ""),

        policyEndDate:
            String(body.policyEndDate || ""),

        policyStatus:
            String(body.policyStatus || ""),

        dateOfLoss:
            String(body.dateOfLoss || ""),

        lossCode:
            String(body.lossType || ""),

        partGroupCode:
            String(body.primaryDamageGroup || ""),

        estimatedPartsCost:
            String(body.estimatedPartsCost || ""),

        garageType:
            String(body.garageType || ""),

        firFiled:
            body.firFiled ?? false,

        validDrivingLicence:
            body.validDrivingLicence ?? false,

        lossDescription:
            String(body.lossDescription || "")
    },

    wfData: {

        claimId:
            bh.local.claimId,

        policyNumber:
            String(body.policyNo || ""),

        customerName:
            String(body.customerName || ""),

        vehicleRegistration:
            String(body.vehicleRegistration || ""),

        vehicleType:
            String(body.vehicleType || ""),

        yearOfManufacture:
            String(body.yearOfManufacture || ""),

        idv:
            String(body.idv || ""),

        policyStartDate:
            String(body.policyStartDate || ""),

        policyEndDate:
            String(body.policyEndDate || ""),

        policyStatus:
            String(body.policyStatus || ""),

        dateOfLoss:
            String(body.dateOfLoss || ""),

        lossCode:
            String(body.lossType || ""),

        partGroupCode:
            String(body.primaryDamageGroup || ""),

        estimatedPartsCost:
            String(body.estimatedPartsCost || ""),

        garageType:
            String(body.garageType || ""),

        firFiled:
            body.firFiled ?? false,

        validDrivingLicence:
            body.validDrivingLicence ?? false,

        lossDescription:
            String(body.lossDescription || "")
    }
};


console.log(
    "CASE BODY:",
    JSON.stringify(
        bh.local.caseCreationRequest,
        null,
        2
    )
);

console.log(
"========== ERROR HANDLER =========="
);

console.log(
"Error:",
bh.error
);

// =====================================================
// DEFAULT
// =====================================================

let statusCode = 500;

let message = "Internal server error";

// =====================================================
// GET ERROR STATUS
// =====================================================

if (
bh.error &&
bh.error.response &&
bh.error.response.statusCode
) {

statusCode =
    Number(
        bh.error.response.statusCode
    );

}

// =====================================================
// FALLBACK FROM ERROR MESSAGE
// =====================================================

const errorMessage =
String(
bh.error?.message ||
bh.error ||
""
);

// =====================================================
// DETECT COMMON HTTP STATUS
// =====================================================

if (
errorMessage.includes("Response code 400")
) {

statusCode = 400;

}

else if (
errorMessage.includes("Response code 401")
) {

statusCode = 401;

}

else if (
errorMessage.includes("Response code 403")
) {

statusCode = 403;

}

else if (
errorMessage.includes("Response code 404")
) {

statusCode = 404;

}

else if (
errorMessage.includes("Response code 500")
) {

statusCode = 500;

}

else if (
errorMessage.includes("Response code 502")
) {

statusCode = 502;

}

else if (
errorMessage.includes("Response code 503")
) {

statusCode = 503;

}

// =====================================================
// ERROR MESSAGE
// =====================================================

if (statusCode === 400) {

message =
    "Bad request.";

}

else if (statusCode === 401) {

message =
    "Authentication failed.";

}

else if (statusCode === 403) {

message =
    "Access denied.";

}

else if (statusCode === 404) {

message =
    "Requested service or resource not found.";

}

else if (statusCode >= 500) {

message =
    "Internal server or external service error.";

}

// =====================================================
// FINAL ERROR RESPONSE
// =====================================================

bh.local.responseStatus =
statusCode;

bh.local.response = {

success: false,

message: message,

statusCode: statusCode

};

console.log(
"========== ERROR RESPONSE =========="
);

console.log(
JSON.stringify(
bh.local.response,
null,
2
)
);

const body = bh.input.body || {};

const claimId = String(
    bh.input.params.id || ""
).trim();

const action = String(
    body.action || ""
).trim().toUpperCase();

const revisedNetPayable =
    body.revised_net_payable !== undefined &&
    body.revised_net_payable !== null &&
    body.revised_net_payable !== ""
        ? Number(body.revised_net_payable)
        : null;

const remark = String(
    body.remark || ""
).trim();

if (!claimId) {
    throw new Error("Claim ID is missing.");
}

bh.local.claimId = claimId;
bh.local.surveyorAction = action;
bh.local.revisedNetPayable = revisedNetPayable;
bh.local.surveyorRemark = remark;

console.log("CLAIM ID FROM URL =>", bh.local.claimId);

console.log("===== FIND RESULT =====");
console.log(bh.local.GetResult);

const result = bh.local.GetResult || [];

if (!Array.isArray(result) || result.length === 0) {
    bh.local.responseStatus = 404;

    bh.local.response = {
        success: false,
        message: "Claim not found",
        claimId: bh.local.claimId
    };

    throw new Error("Claim not found: " + bh.local.claimId);
}

const claim = result[0];

let surveyorNetPayable = claim.system_net_payable;

if (bh.local.surveyorAction === "REVISE") {
    surveyorNetPayable = bh.local.revisedNetPayable;
}

if (bh.local.surveyorAction === "CONFIRM") {
    surveyorNetPayable = claim.system_net_payable;
}

if (bh.local.surveyorAction === "REPUDIATE") {
    surveyorNetPayable = 0;
}

bh.local.updateObject = {
    claim_id: bh.local.claimId,

    surveyor_net_payable: surveyorNetPayable,

    surveyor_remarks: bh.local.surveyorRemark,

    status:
        bh.local.surveyorAction === "REPUDIATE"
            ? "REPUDIATED"
            : "SURVEYOR_COMPLETED",

    updated_at: new Date().toISOString()
};

console.log("===== UPDATE OBJECT =====");
console.log(bh.local.updateObject);

console.log("===== UPDATE OBJECT =====");
console.log(bh.local.updateObject);

console.log("================================");
console.log("SURVEYOR UPDATE RESPONSE");
console.log("UpdateResult =", bh.local.UpdateResult);
console.log("Claim ID =", bh.local.claimId);
console.log("================================");

bh.local.responseStatus = 200;

bh.local.response = {
    success: true,
    message: "Surveyor action updated successfully.",
    claimId: bh.local.claimId,
    action: bh.local.surveyorAction,
    revisedNetPayable: bh.local.revisedNetPayable,
    remark: bh.local.surveyorRemark,
    updateResult: bh.local.UpdateResult
};

console.log("responseStatus =", bh.local.responseStatus);
console.log("response =", bh.local.response);

const body = bh.input.body || {};

const claimId =
    String(bh.input.params.id || "").trim();

const action =
    String(body.action || "").trim().toUpperCase();

const remark =
    String(body.remark || "").trim();

if (!claimId) {
    throw new Error("Claim ID is missing.");
}

if (!action) {
    throw new Error("Manager action is required.");
}

if (action !== "APPROVE" && action !== "REJECT") {
    throw new Error(
        "Invalid manager action. Use APPROVE or REJECT."
    );
}

if (!remark) {
    throw new Error("Manager remark is required.");
}

bh.local.claimId = claimId;
bh.local.managerAction = action;
bh.local.managerRemark = remark;

console.log("================================");
console.log("MANAGER ACTION");
console.log("Claim ID =", bh.local.claimId);
console.log("Action =", bh.local.managerAction);
console.log("Remark =", bh.local.managerRemark);
console.log("================================");

console.log("================================");
console.log("MANAGER - FIND RESULT");
console.log("Claim ID =", bh.local.claimId);
console.log("GetResult =", bh.local.GetResult);
console.log("================================");

const result = bh.local.GetResult || [];

if (!Array.isArray(result) || result.length === 0) {

    bh.local.responseStatus = 404;

    bh.local.response = {
        success: false,
        message: "Claim not found.",
        claimId: bh.local.claimId
    };

    throw new Error(
        "Claim not found: " + bh.local.claimId
    );
}

const claim = result[0];

let newStatus = "";
let settlementRef = null;

if (bh.local.managerAction === "APPROVE") {

    newStatus = "SETTLED";

    const year = new Date().getFullYear();

    const randomNumber =
        Math.floor(100000 + Math.random() * 900000);

    settlementRef =
        "STL-" + year + "-" + randomNumber;

} else if (bh.local.managerAction === "REJECT") {

    newStatus = "REPUDIATED";

    settlementRef = null;
}

bh.local.updateObject = {

    claim_id: bh.local.claimId,

    manager_remarks:
        bh.local.managerRemark,

    status:
        newStatus,

    settlement_ref:
        settlementRef,

    updated_at:
        new Date().toISOString()
};

console.log("================================");
console.log("MANAGER UPDATE OBJECT");
console.log(bh.local.updateObject);
console.log("================================");

console.log("================================");
console.log("MANAGER UPDATE RESULT");
console.log("UpdateResult =", bh.local.UpdateResult);
console.log("================================");

bh.local.responseStatus = 200;

bh.local.response = {

    success: true,

    message:
        bh.local.managerAction === "APPROVE"
            ? "Claim approved and settled successfully."
            : "Claim rejected and repudiated successfully.",

    claimId:
        bh.local.claimId,

    action:
        bh.local.managerAction,

    status:
        bh.local.updateObject.status,

    settlementRef:
        bh.local.updateObject.settlement_ref,

    remark:
